import {emptyState,validateBundle,mergeBundle,day,canonicalURL} from './core.mjs';
import {saveLocalFile,readLocalFile,fileSize,fileKind,storedZip} from './files.mjs';
import {taskParts,researchTask,fullPrompt,overview,actualStage,visibleResults,normalizeTask} from './workspace.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='startrail.memory.v1',ACTIVE='startrail.active.v3';let state=emptyState(),active=null,mode='work',draftFiles=[],thumbURLs=[];
try{const raw=localStorage.getItem(KEY);if(raw){state=validateBundle(JSON.parse(raw));state.tasks=state.tasks.map(normalizeTask);}draftFiles=JSON.parse(localStorage.getItem('startrail.draft-files.v1')||'[]');if(!Array.isArray(draftFiles))draftFiles=[];mode=localStorage.getItem('startrail.mode.v1')==='study'?'study':'work';active=state.tasks.find(t=>t.id===localStorage.getItem(ACTIVE))||null;}catch{toast('部分旧记录无法读取，请从备份恢复；原记录暂未覆盖。');}
function id(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem('startrail.draft-files.v1',JSON.stringify(draftFiles));localStorage.setItem('startrail.mode.v1',mode);if(active)localStorage.setItem(ACTIVE,active.id);else localStorage.removeItem(ACTIVE);$('#saveStatus').textContent='已保存于当前浏览器';}catch{toast('浏览器存储不可用，请从「更多」导出备份');$('#saveStatus').textContent='尚未持久保存，请导出备份';}}
function modal(title,html){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();}
function safeURL(raw){try{const u=new URL(raw);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password;}catch{return false;}}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadJSON(value,name){saveBlob(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),name);}
function setMode(next){mode=next;$('#request').placeholder=mode==='study'?'根据课程要求查找近期与历史案例，制定作业计划，并给出分步执行 Prompt。也可以直接上传作业截图。':'比较三款竞品近三个月的新玩法，整理有来源的案例，给出可执行建议。也可以直接上传工作要求。';$$('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===mode));if(!active){$('#deliverable').value=mode==='study'?'课程作业方案':'研究简报';}updateOptionSummary();}
function updateOptionSummary(){$('#optionSummary').textContent=$('#deliverable').value+' · 近期上升与历史对照';}
function fileContext(){return active?(active.attachments??=[]):draftFiles;}
function newTask(){active=null;draftFiles=[];$('#request').value='';$('#focus').value='';$('#profile').value='general';$('#workspace').hidden=true;$('#welcome').hidden=false;$('#starter').hidden=false;$('.composer').classList.remove('hidden-composer','saved-request');$('#generateBtn').innerHTML='生成研究方案 <span>↗</span>';$('#editingLabel').textContent='先告诉我，你要完成什么';$('#promptLibrary').open=false;$('#fileProgress').hidden=true;setMode(mode);renderFiles();persist();$('#request').focus();window.scrollTo({top:0,behavior:'smooth'});}
function restoreTask(task){active=task;mode=task.mode==='study'?'study':'work';setMode(mode);$('#request').value=task.brief||task.topic||'';$('#focus').value=task.focus||'';$('#profile').value=task.profile==='bag-design'?'bag-design':'general';$('#deliverable').value=task.deliverable||(mode==='study'?'课程作业方案':'研究简报');updateOptionSummary();renderWorkspace();persist();renderFiles();}
function renderWorkspace(){if(!active)return;$('#welcome').hidden=true;$('#starter').hidden=true;$('#workspace').hidden=false;$('.composer').classList.add('hidden-composer');$('.composer').classList.remove('saved-request');$('#projectTitle').textContent=active.topic;const stage=actualStage(active);$('#stageLabel').textContent=stage.label;$('#stageTime').textContent='记录更新 '+(active.updated_at||active.plan_generated_at||active.created_at||'').slice(0,10);$('#stageDetail').textContent=stage.detail;$('#stageStrip').innerHTML=['任务已整理','资料研究','分析核验','成果交付'].map((label,i)=>`<li class="${i<stage.index?'done':i===stage.index?'current':''}" ${i===stage.index?'aria-current="step"':''}>${label}</li>`).join('');renderResults();renderPrompts();renderQuality();}
function renderResults(){const task=active,plan=overview(task),results=visibleResults(task);$('#resultCount').textContent=results.length?'已提供 '+results.filter(r=>r.status!=='needs_input').length+' 项 · 待确认 '+results.filter(r=>r.status==='needs_input').length+' 项':'方案已生成 · 研究尚未执行';const cards=results.map(r=>`<article class="result-card"><div class="card-meta">${escapeHTML(r.part||'研究结果')}<span class="badge">${r.status==='needs_input'?'待你确认':'已提供 · 见来源说明'}</span></div><h3>${escapeHTML(r.title||'研究成果')}</h3><div class="content">${escapeHTML(r.content||r.summary||'')}</div>${safeURL(r.url)?`<a href="${escapeHTML(r.url)}" target="_blank" rel="noopener noreferrer" class="result-attachment">打开成果文件 ↗</a>`:''}${r.file_ref?`<div class="source">文件：${escapeHTML(r.file_ref)}</div>`:''}<div class="source">来源：${escapeHTML(r.source||'未注明，需补充')}<br>${escapeHTML(r.verification||'是否可作为事实引用，需结合原始证据核验。')}</div></article>`).join('');$('#resultCards').innerHTML=`<article class="result-card"><div class="card-meta">研究方案 <span class="badge">可编辑 · 非研究结论</span></div><h3>这项任务会怎样完成</h3><ul class="plan-list"><li><b>目标</b><span>${escapeHTML(plan.goal)}</span></li><li><b>交付</b><span>${escapeHTML(plan.deliverable)}</span></li><li><b>资料范围</b><span>近期上升信号 ＋ 历史热点对照<br><span class="note">近三个月：${escapeHTML(plan.recent)}。指定的历史范围独立保障覆盖。</span></span></li><li><b>推进方式</b><span>先复用已有资料，再检索、核验和交付。<br><span class="note">${plan.parts} 个可展开的 Prompt Part，位于下方。</span></span></li></ul></article>${cards}${results.length?'':'<div class="danger-note">这里将显示真正完成的分析和文件。当前只有研究方案，不把待执行内容当成成果。</div>'}`;}
function renderPrompts(){const parts=taskParts(active);$('#promptLibrary').open=false;$('#promptSubtitle').textContent=active.profile==='bag-design'?'按「包袋设计作业流程」优化版 · Part 0—10':'按任务目标与星迹检索规则生成';$('#promptParts').innerHTML=parts.map(p=>`<details class="part" data-part="${p.part}"><summary><span>Part ${p.part} · ${escapeHTML(p.name)}</span><small>查看执行要求</small></summary><div class="part-body"><p>准备：${escapeHTML(p.input)}<br>将得到：${escapeHTML(p.output)}<br>验收：${escapeHTML(p.check)}</p><pre class="prompt-text">${escapeHTML(fullPrompt(active,p))}</pre><div class="part-actions"><button class="secondary" data-copy-part="${p.part}">复制此 Part</button><button class="quiet" data-save-part="${p.part}">下载 .txt</button></div></div></details>`).join('');$$('[data-copy-part]').forEach(b=>b.onclick=()=>copyText(fullPrompt(active,parts.find(p=>p.part===Number(b.dataset.copyPart)))));$$('[data-save-part]').forEach(b=>b.onclick=()=>{const p=parts.find(p=>p.part===Number(b.dataset.savePart));saveBlob(new Blob([fullPrompt(active,p)],{type:'text/plain;charset=utf-8'}),'Part-'+p.part+'-'+p.name+'.txt');});}
function renderQuality(){const task=active;const sources=state.sources.filter(s=>(s.task_ids||[]).includes(task.id));const verified=sources.filter(s=>s.verification==='verified').length;$('#qualityInfo').innerHTML=`<p>附件 ${(task.attachments||[]).length} 份<br>已收录来源 ${sources.length} 条，其中记录已核验 ${verified} 条。</p><p>重要结论需附来源和时间依据。日期、材质和增长数据不明时标待验证；不以累计热度冒充增长。</p><p>生成计划、复制 Prompt、导出任务包均不代表已执行。</p>${sources.length?'<details class="sources-list"><summary>查看来源目录</summary><p>状态来自执行记录，页面不会自动核验正文或图片。</p>'+sources.filter(s=>safeURL(s.url)).map(s=>`<div class="source-entry"><a href="${escapeHTML(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(s.title||s.brand||'原始来源')} ↗</a><small>${s.verification==='verified'?'记录已核验':'待核验'}${s.visual_review_completed===false?' · 图片尚未分析':''}</small><p>${escapeHTML(s.summary||'')}</p></div>`).join('')+'</details>':''}`;}
function executionText(task){const parts=taskParts(task);return `请使用 $startrail-search 继续此研究任务，先核对当前已有记录和实际文件。\n任务编号：${task.id}\n当前状态：${actualStage(task).label}\n任务记录：${JSON.stringify(task.workflow_progress||{})}\n已有实际交付：${JSON.stringify(visibleResults(task))}\n来源对话：${task.origin_thread||'当前任务'}\n本地项目文件：${(task.project_files||[]).join('、')||'无'}。仅在实际可访问时读取，不可访问就说明。\n只推进当前需要执行的部分，缺少前置先补充，不越过用户尚未确定的审美、品牌或试色等决定。\n\n`+parts.map(p=>fullPrompt(task,p)).join('\n\n────────\n\n');}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制。请粘贴到 Codex 执行。');}catch{modal('复制执行任务','<p>选中文字后，按 ⌘C 或 Ctrl+C 复制。</p><textarea id="copyFallback" readonly aria-label="待复制内容"></textarea>');$('#copyFallback').value=text;$('#copyFallback').select();}}
function currentBundle(task){const sourceIds=new Set(state.sources.filter(s=>(s.task_ids||[]).includes(task.id)).map(s=>s.id));return {schema_version:1,exported_at:new Date().toISOString(),tasks:[task],sources:state.sources.filter(s=>sourceIds.has(s.id)),searches:state.searches.filter(s=>s.task_id===task.id),observations:state.observations.filter(o=>sourceIds.has(o.source_id)),deliveries:state.deliveries.filter(d=>d.task_id===task.id)};}
async function exportTask(){if(!active)return;$('#exportTask').disabled=true;try{const encoder=new TextEncoder(),entries=[{name:'执行任务.txt',bytes:encoder.encode(executionText(active))},{name:'startrail-memory.json',bytes:encoder.encode(JSON.stringify(currentBundle(active),null,2))}];const missing=[];for(const meta of active.attachments||[]){const file=await readLocalFile(meta.id);if(file)entries.push({name:'attachments/'+meta.id+'-'+meta.name.replace(/[\\/:*?"<>|]/g,'_'),bytes:new Uint8Array(await file.arrayBuffer())});else missing.push(meta.name);}if(missing.length){modal('需要补齐原文件',`<p>此浏览器只有以下文件的记录，没有原文件内容：${escapeHTML(missing.join('、'))}。</p><p>请点击「编辑要求」重新添加，或者执行时直接在 Codex 补传。</p>`);return;}saveBlob(storedZip(entries),'星迹执行任务-'+day()+'.zip');toast('已导出任务包，包含执行要求、记录与原附件。');}catch(err){toast('导出失败：'+err.message);}finally{$('#exportTask').disabled=false;}}
$('#taskForm').onsubmit=e=>{e.preventDefault();const brief=$('#request').value.trim();if(!brief){$('#request').focus();return;}const profile=$('#profile').value==='bag-design'?'bag-design':'general';if(active){Object.assign(active,{topic:brief.split('\n')[0].slice(0,140),brief,mode,profile,focus:$('#focus').value.trim(),deliverable:$('#deliverable').value,updated_at:new Date().toISOString()});toast('已更新方案。原研究结果保留，需按新要求复核。');}else{const candidate=researchTask({id:id(),topic:brief,mode,profile,focus:$('#focus').value.trim(),deliverable:$('#deliverable').value,attachments:[...draftFiles]});const existing=state.tasks.find(t=>(t.brief||t.topic||'').trim().toLowerCase()===brief.toLowerCase()&&t.mode===mode&&(t.profile||'general')===profile&&(t.deliverable||'')===candidate.deliverable&&(t.focus||'')===candidate.focus);if(existing){existing.attachments=[...new Map([...(existing.attachments||[]),...draftFiles].map(f=>[f.sha256||f.id,f])).values()];active=existing;toast('相同任务已存在，已接续已有记录。');}else{active=candidate;state.tasks.unshift(active);}draftFiles=[];}persist();renderWorkspace();$('#workspace').scrollIntoView({behavior:'smooth',block:'start'});};
$('#editTask').onclick=()=>{$('.composer').classList.remove('hidden-composer');$('.composer').classList.add('saved-request');$('#generateBtn').innerHTML='更新研究方案 <span>↗</span>';$('#editingLabel').textContent='修改要求，或补充资料';renderFiles();$('.composer').scrollIntoView({behavior:'smooth',block:'start'});};
$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('#deliverable').onchange=updateOptionSummary;$('#newBtn').onclick=newTask;$('#homeLink').onclick=e=>{e.preventDefault();newTask();};
$$('[data-example]').forEach(b=>b.onclick=()=>{newTask();const type=b.dataset.example;setMode(type==='work'?'work':'study');$('#request').value=type==='work'?'调研同类产品近三个月上升最快的新玩法，对比过往热点，整理有来源的竞品案例和可执行建议。':type==='study'?'根据课程要求整理研究问题，查找最新案例与历史资料，制定分步计划，交付可引用的研究简报。':'我需要完成包袋课程作业：约100个参考素材，2个品牌近两年风格研究与未来一年趋势假设，4个风格各5款设计，最后完成上色、三视图、PPT与展板。侧重版型、材质、配色、时尚感和风格，不做用户调查或裁片。';if(type==='bag'){$('#profile').value='bag-design';$('#focus').value='外观设计：版型、材质、配色、时尚感、风格';$('#deliverable').value='课程作业方案';}updateOptionSummary();$('#request').focus();});
function history(){modal('我的任务',state.tasks.length?state.tasks.map(t=>`<div class="task-row"><div><strong>${escapeHTML(t.topic||'未命名任务')}</strong><small>${t.mode==='study'?'学习':'工作'} · ${(t.updated_at||t.created_at||'').slice(0,10)} · ${escapeHTML(actualStage(t).label)}</small></div><button class="quiet" data-open-task="${escapeHTML(t.id)}">继续 ↗</button></div>`).join(''):'<p class="empty-note">还没有任务。先写下你要完成的事，再点击「生成研究方案」。</p>');$$('[data-open-task]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(x=>x.id===b.dataset.openTask);if(t){$('#dialog').close();restoreTask(t);}});}
$('#historyBtn').onclick=history;$('#moreBtn').onclick=()=>{modal('项目与资料','<p>任务和附件保存在此浏览器。导出备份可用于迁移；导入文件可接续执行进度与实际成果。</p><div class="dialog-actions"><button id="menuImport" class="secondary">导入项目或成果</button><button id="menuExport" class="secondary">导出全部记录</button></div>');$('#menuImport').onclick=()=>$('#importInput').click();$('#menuExport').onclick=()=>downloadJSON({...state,exported_at:new Date().toISOString()},'startrail-memory-'+day()+'.json');};
$('#importResults').onclick=()=>$('#importInput').click();$('#importInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1048576)throw Error('JSON记录超过10MB，请分批导入');const incoming=validateBundle(JSON.parse(await file.text()));incoming.tasks=incoming.tasks.map(normalizeTask);state=mergeBundle(state,incoming);const selected=incoming.tasks[0];if(selected)active=state.tasks.find(t=>t.id===selected.id);else if(active)active=state.tasks.find(t=>t.id===active.id)||null;persist();$('#dialog').close();if(active)restoreTask(active);toast('已合并记录，较新进度与既有成果保留。');}catch(err){toast('导入失败：'+err.message);}finally{e.target.value='';}};
async function addFiles(files){const list=fileContext(),batch=[...files],label=$('#fileProgress');label.hidden=false;$('#generateBtn').disabled=true;let done=0,saved=0;for(const file of batch){label.innerHTML=`正在保存 ${done+1}/${batch.length}：${escapeHTML(file.name)}<progress max="${batch.length}" value="${done}"></progress>`;try{if(list.length>=20)throw Error('每任务最多20份附件');if(file.size>25*1048576)throw Error('单文件上限25MB');if(list.reduce((n,x)=>n+x.size,0)+file.size>50*1048576)throw Error('任务附件总量上限50MB');const kind=fileKind(file),bytes=await file.arrayBuffer();const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');if(list.some(x=>x.sha256===hash)){done++;continue;}const key=id();await saveLocalFile(key,file);list.push({id:key,name:file.name,size:file.size,type:file.type,kind,sha256:hash,created_at:new Date().toISOString()});saved++;}catch(err){toast(file.name+'：'+err.message);}done++;}persist();await renderFiles();label.innerHTML=`已保存 ${saved} 份附件，仅保存在当前浏览器。<progress max="${batch.length}" value="${done}"></progress>`;$('#generateBtn').disabled=false;}
async function renderFiles(){thumbURLs.forEach(url=>URL.revokeObjectURL(url));thumbURLs=[];const list=fileContext(),target=$('#fileList');target.innerHTML=list.map(f=>`<div class="file-chip"><span data-thumb="${escapeHTML(f.id)}">${f.kind==='image'?'▧':'▤'}</span><div><button type="button" data-preview="${escapeHTML(f.id)}" title="预览 ${escapeHTML(f.name)}">${escapeHTML(f.name)}</button><small>${fileSize(f.size)}</small></div><button type="button" data-remove="${escapeHTML(f.id)}" aria-label="移除 ${escapeHTML(f.name)}">×</button></div>`).join('');$$('[data-preview]').forEach(b=>b.onclick=()=>previewFile(b.dataset.preview));$$('[data-remove]').forEach(b=>b.onclick=()=>{if(active)active.attachments=(active.attachments||[]).filter(f=>f.id!==b.dataset.remove);else draftFiles=draftFiles.filter(f=>f.id!==b.dataset.remove);persist();renderFiles();});for(const meta of list.filter(f=>f.kind==='image')){try{const file=await readLocalFile(meta.id);const node=$$('[data-thumb]').find(n=>n.dataset.thumb===meta.id);if(!node||!file)continue;const url=URL.createObjectURL(file);thumbURLs.push(url);const image=document.createElement('img');image.src=url;image.alt=meta.name;node.replaceWith(image);}catch{}}}
async function previewFile(key){const meta=fileContext().find(f=>f.id===key);if(!meta)return;try{const file=await readLocalFile(key);if(!file){toast('未找到原文件，请重新添加。');return;}modal(meta.name,'<div id="previewBody"></div><div class="dialog-actions"><button id="downloadOriginal" class="secondary">下载原文件</button></div>');if(meta.kind==='image'){const image=document.createElement('img'),url=URL.createObjectURL(file);image.src=url;image.alt=meta.name;image.className='preview';$('#previewBody').append(image);$('#dialog').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}else if(meta.kind==='text'){const pre=document.createElement('pre');pre.className='prompt-text';pre.textContent=(await file.slice(0,100000).text())+(file.size>100000?'\n…仅预览前100KB':'');$('#previewBody').append(pre);}else $('#previewBody').innerHTML='<p>文件已保存。导出任务包后交给 Codex 读取；当前页面未解析此文档。</p>';$('#downloadOriginal').onclick=()=>saveBlob(file,meta.name);}catch(err){toast('文件读取失败：'+err.message);}}
$('#attachBtn').onclick=()=>$('#attachmentInput').click();$('#attachmentInput').onchange=e=>{addFiles(e.target.files);e.target.value='';};const drop=$('#taskForm');drop.ondragover=e=>{e.preventDefault();$('#dropZone').classList.add('dragover');};drop.ondragleave=()=>$('#dropZone').classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();$('#dropZone').classList.remove('dragover');addFiles(e.dataTransfer.files);};
$('#copyTask').onclick=()=>active&&copyText(executionText(active));$('#exportTask').onclick=exportTask;$('#closeDialog').onclick=()=>$('#dialog').close();$('#helpBtn').onclick=()=>modal('三步使用星迹','<p><b>1. 提交任务</b><br>选择工作或学习，写下目标，添加课程要求、参考图或工作资料。</p><p><b>2. 获得方案</b><br>点击「生成研究方案」。任务范围和交付会出现在主区；进度条只表示当前记录的阶段。需要时展开「分步执行 Prompt」。</p><p><b>3. 执行与交付</b><br>复制执行任务或导出附件包，在 Codex 中继续。收到结果后，从「更多」导入成果文件。实际结论和文件会显示在方案下方。</p><p>当前版本尚未连接自动执行服务，不会自动搜索或在后台运行。没有证据的内容标待验证，已有任务可从「我的任务」继续。</p>');
$('#promptLibrary').ontoggle=()=>{$('.disclosure').textContent=$('#promptLibrary').open?'收起 −':'点击查看 ＋';};
setMode(mode);if(active)restoreTask(active);else renderFiles();
